_static_webdav_follow_mode() {
    cat <<-'ARGCEOF'
	on	this computer takes the server's setup on every sync and sends none of its own; a change made here is replaced, a copy kept in the sync folder
	off	both ways, as before
ARGCEOF
}

_static_s3_auto_interval() {
    cat <<-'ARGCEOF'
	off	only when asked
	3	
	15	
	30	
	60	
ARGCEOF
}

_static_s3_follow_mode() {
    cat <<-'ARGCEOF'
	on	this computer takes the server's setup on every sync and sends none of its own
	off	both ways, as before
ARGCEOF
}

_static_group_template_kind() {
    cat <<-'ARGCEOF'
	smart	hard turns to the strongest model, easy ones to a cheap one, a classifier telling them apart
	thrifty	a cheap model first, the strongest for high reasoning or when the cheap ones fail
	steady	the strongest model of each of up to three providers, each behind the other
ARGCEOF
}

_static_accounts_switch_only_agent() {
    cat <<-'ARGCEOF'
	codex	only switch Codex's own sign-in to an account with room; its requests go straight to OpenAI, never through magpie
	claude	only switch Claude Code's own sign-in to an account with room; magpie serves no requests on the Claude accounts
ARGCEOF
}

_static_lan_state() {
    cat <<-'ARGCEOF'
	on	other computers on this network reach it, with a gateway key
	off	only this computer reaches it: it listens on 127.0.0.1
ARGCEOF
}

_static_update_channel_channel() {
    cat <<-'ARGCEOF'
	stable	one a week
	daily	a day that passed its tests
	every	version as it comes out (the default)
ARGCEOF
}

_static_update_auto_mode() {
    cat <<-'ARGCEOF'
	download	
	notify	for metered networks
ARGCEOF
}
